const setTicketStatus = `-- name: SetTicketStatus :exec
UPDATE ticket
SET status = $1::text,
    last_reply_at = CASE WHEN $2::boolean THEN $3::timestamptz ELSE last_reply_at END,
    closed_at = CASE WHEN $1::text = 'closed' THEN $3::timestamptz ELSE NULL END,
    updated_at = $3::timestamptz
WHERE id = $4
`

type SetTicketStatusParams struct {
	Status     string
	TouchReply bool
	Now        pgtype.Timestamptz
	ID         int64
}

// touch_reply 为真时把最近回复时间推到 now（有新消息）；关闭时记关闭时间，重新打开时清掉
func (q *Queries) SetTicketStatus(ctx context.Context, arg SetTicketStatusParams) error {
	_, err := q.db.Exec(ctx, setTicketStatus,
		arg.Status,
		arg.TouchReply,
		arg.Now,
		arg.ID,
	)
	return err
}

